function.arguments:
{"command": "cat > /problem/src/gemm.cu << 'CUEOF'
#include "gemm.cuh"

#include <cuda_runtime.h>
#include <stdio.h>

// Target tile size for the block (output tile of C)
#define TILE 32
// Number of threads per block
#define BLOCK_X 16
#define BLOCK_Y 16

// Shared memory with padding to avoid bank conflicts
__shared__ float As[TILE][TILE + 1];  // 33-wide to break 16-way bank conflicts
__shared__ float Bs[TILE + 1][TILE];  // 33-high to break 16-way bank conflicts

// Each thread computes 2x2 output elements for better register usage
// Registers: 4 accumulator values per thread
__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    // Each thread computes a 2x2 block of C
    const int subT = 2;  // sub-tile per thread
    const int subTilesX = TILE / subT;  // 16
    const int subTilesY = TILE / subT;  // 16

    // Thread's position within the block in sub-tile units
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    // Which sub-tile column/row this thread handles
    const int subX = tx / subT;
    const int subY = ty / subT;

    // Offset within the sub-tile
    const int inX = tx % subT;  // 0 or 1
    const int inY = ty % subT;  // 0 or 1

    // Global row/col this thread is responsible for
    const int baseRow = blockIdx.y * TILE + subY * subT + inY;
    const int baseCol = blockIdx.x * TILE + subX * subT + inX;

    // Accumulators for the 4 elements (2 rows x 2 cols)
    float acc00 = 0.0f, acc01 = 0.0f;  // baseRow x (baseCol, baseCol+1)
    float acc10 = 0.0f, acc11 = 0.0f;  // (baseRow+1) x (baseCol, baseCol+1)

    const int numTiles = (N + TILE - 1) / TILE;

    for (int t = 0; t < numTiles; ++t) {
        // Load A sub-tile into shared memory (coalesced read)
        // Each thread in the x-direction loads one column of the A tile
        // Each thread in the y-direction loads one row of the A tile
        const int aRow = baseRow;
        const int aCol = t * TILE + tx;
        As[ty][tx] = (aRow < N && aCol < N) ? A[aRow * N + aCol] : 0.0f;

        // Load B sub-tile into shared memory (coalesced read)
        const int bRow = t * TILE + ty;
        const int bCol = baseCol;
        Bs[ty][tx] = (bRow < N && bCol < N) ? B[bRow * N + bCol] : 0.0f;

        __syncthreads();

        // Compute dot products using the 2x2 register tiling
        // Thread (tx,ty) has As[ty][0:TILE] and Bs[0:TILE][tx]
        // It contributes to 4 output positions:
        //   C[baseRow][baseCol], C[baseRow][baseCol+1]
        //   C[baseRow+1][baseCol], C[baseRow+1][baseCol+1]

#pragma unroll
        for (int k = 0; k < TILE; ++k) {
            float a0 = As[ty][k];
            float a1 = (inY == 1) ? As[ty + 1][k] : 0.0f;
            float b0 = Bs[k][tx];
            float b1 = (inX == 1) ? Bs[k][tx + 1] : 0.0f;

            // 2x2 outer product accumulated into 4 accumulators
            acc00 += a0 * b0;
            acc01 += a0 * b1;
            acc10 += a1 * b0;
            acc11 += a1 * b1;
        }

        __syncthreads();
    }

    // Store results
    if (baseRow < N && baseCol < N)
        C[baseRow * N + baseCol] = acc00;
    if (baseRow < N && baseCol + 1 < N)
        C[baseRow * N + baseCol + 1] = acc01;
    if (baseRow + 1 < N && baseCol < N)
        C[(baseRow + 1) * N + baseCol] = acc10;
    if (baseRow + 1 < N && baseCol + 1 < N)
        C[(baseRow + 1) * N + baseCol + 1] = acc11;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    dim3 block(BLOCK_X, BLOCK_Y);
    dim3 grid((N + TILE - 1) / TILE, (N + TILE - 1) / TILE);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
CUEOF
echo "Written gemm.cu""}

