#include "gemm.cuh"

#include <cuda_runtime.h>
#include <stdio.h>

// Target tile size for the block (output tile of C)
#define TILE 32
// Number of threads per block
#define BLOCK_X 16
#define BLOCK_Y 16

// Shared memory with padding to avoid bank conflicts
__shared__ float As[TILE][TILE + 1];  // 33-wide to break 16-way bank conflicts
__shared__ float Bs[TILE + 1][TILE];  // 33-high to break 16-way bank conflicts

// Each thread computes 2x2 output elements for better register usage
// Registers: 4 accumulator values per thread
__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
