#include "gemm.cuh"

#include <cuda_runtime.h>

#define TILE 32
#define TILE_SM 16
#define BLOCK_SIZE 16
#define PAD 1

__shared__ float As[TILE][TILE + PAD];
__shared__ float Bs[TILE + PAD][TILE];

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int row0 = blockIdx.y * TILE + 2 * ty;
    const int row1 = row0 + 1;
    const int col0 = blockIdx.x * TILE + 2 * tx;
    const int col1 = col0 + 1;

    const int numTiles = (N + TILE - 1) / TILE;

    float acc00 = 0.0f, acc01 = 0.0f;
    float acc10 = 0.0f, acc11 = 0.0f;

    for (int t = 0; t < numTiles; ++t) {
        const int baseK = t * TILE_SM;
        // Pass 0: top-left
        As[ty][tx] = (row0 < N && baseK + tx < N) ? A[row0 * N + baseK + tx] : 0.0f;
        Bs[ty][tx] = (baseK + ty < N && col0 < N) ? B[(baseK + ty) * N + col0] : 0.0f;
        __syncthreads();
        // Pass 1: bottom-left
        As[ty + TILE_SM][tx] = (row1 < N && baseK + tx < N) ? A[row1 * N + baseK + tx] : 0.0f;
        Bs[ty + TILE_SM][tx] = (baseK + 16 + ty < N && col0 < N) ? B[(baseK + 16 + ty) * N + col0] : 0.0f;
        __syncthreads();
        // Pass 2: top-right
        As[ty][tx + TILE_SM] = (row0 < N && baseK + 16 + tx < N) ? A[row0 * N + baseK + 16 + tx] : 0.0f;
        Bs[ty][tx + TILE_SM] = (baseK + ty < N && col1 < N) ? B[(baseK + ty) * N + col1] : 0.0f;
        __syncthreads();
        // Pass 3: bottom-right
        As[ty + TILE_SM][tx + TILE_SM] = (row1 < N && baseK + 16 + tx < N) ? A[row1 * N + baseK + 16 + tx] : 0.0f;
        Bs[ty + TILE_SM][tx + TILE_SM] = (baseK + 16 + ty < N && col1 < N) ? B[(baseK + 16 + ty) * N + col1] : 0.0f;
        __syncthreads();

#pragma unroll
        for (int k = 0; k < TILE; ++k) {
            acc00 += As[2*ty][k] * Bs[k][tx];
            acc01 += As[2*ty][k] * Bs[k][tx + TILE_SM];
            acc10 += As[2*ty+1][k] * Bs[k][tx];
            acc11 += As[2*ty+1][k] * Bs[k][tx + TILE_SM];
        }
    }

    if (row0 < N && col0 < N) C[row0 * N + col0] = acc00;
    if (row0 < N && col1 < N) C[row0 * N + col1] = acc01;
    if (row1 < N && col0 < N) C[row1 * N + col0] = acc10;
    if (row1 < N && col1 < N) C[row1 * N + col1] = acc11;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    dim3 block(BLOCK_SIZE, BLOCK_SIZE);
    dim3 grid((N + TILE - 1) / TILE, (N + TILE - 1) / TILE);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
CUEOF
