#include "gemm.cuh"

#include <cuda_runtime.h>

#define TILE 32
#define TILE_SM 16
#define BLOCK_SIZE_X 32
#define BLOCK_SIZE_Y 16
#define PAD 1

__shared__ float As[TILE][TILE + PAD];
__shared__ float Bs[TILE + PAD][TILE];

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int row0 = blockIdx.y * TILE + 2 * ty;
    const int row1 = row0 + 1;
    const int col = blockIdx.x * TILE + tx;
    const int numTiles = (N + TILE - 1) / TILE;

    float acc0 = 0.0f, acc1 = 0.0f;

    for (int t = 0; t < numTiles; ++t) {
        const int baseK = t * TILE_SM;
        // Pass 0: top half
        As[2*ty][tx] = (row0 < N && baseK + tx < N) ? A[row0 * N + baseK + tx] : 0.0f;
        Bs[ty][tx] = (baseK + ty < N && col < N) ? B[(baseK + ty) * N + col] : 0.0f;
        __syncthreads();
        // Pass 1: bottom half
        As[2*ty+1][tx] = (row1 < N && baseK + tx < N) ? A[row1 * N + baseK + tx] : 0.0f;
        Bs[ty + TILE_SM][tx] = (baseK + TILE_SM + ty < N && col < N) ? B[(baseK + TILE_SM + ty) * N + col] : 0.0f;
        __syncthreads();

#pragma unroll
        for (int k = 0; k < TILE; ++k) {
            acc0 += As[2*ty][k] * Bs[k][tx];
            acc1 += As[2*ty+1][k] * Bs[k][tx];
        }
    }

    if (row0 < N) C[row0 * N + col] = acc0;
    if (row1 < N) C[row1 * N + col] = acc1;
}

