{"command": "cat > /problem/src/gemm.cu << 'CUEOF'
#include "gemm.cuh"

#include <cuda_runtime.h>

// Use a 32-element shared memory tile with BLOCK=32x16
// Each thread handles 2 output elements (2 rows x 1 col)
// 2 passes to load the 32x32 shared memory tile
#define TILE 32
#define BS 16
#define PAD 1

__shared__ float As[TILE][TILE + PAD];
__shared__ float Bs[TILE + PAD][TILE];

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int numTiles = (N + TILE - 1) / TILE;

    // Block handles TILE rows and TILE cols of C
    const int row0 = blockIdx.y * TILE + ty;
    const int row1 = row0 + BS;
    const int col = blockIdx.x * TILE + tx;

    float acc0 = 0.0f, acc1 = 0.0f;

    for (int t = 0; t < numTiles; ++t) {
        // Load shared memory: 2 passes, each thread loads 1 element per pass
        // Pass 0: load top half of As and Bs
        As[ty][tx] = (row0 < N && t*TILE + tx < N) ? A[row0 * N + t*TILE + tx] : 0.0f;
        Bs[ty][tx] = (t*TILE + ty < N && col < N) ? B[(t*TILE + ty) * N + col] : 0.0f;
        __syncthreads();
        // Pass 1: load bottom half
        As[ty + BS][tx] = (row1 < N && t*TILE + tx < N) ? A[row1 * N + t*TILE + tx] : 0.0f;
        Bs[ty + BS][tx] = (t*TILE + BS + ty < N && col < N) ? B[(t*TILE + BS + ty) * N + col] : 0.0f;
        __syncthreads();

#pragma unroll
        for (int k = 0; k < TILE; ++k) {
            acc0 += As[ty][k] * Bs[k][tx];
            acc1 += As[ty + BS][k] * Bs[k][tx];
        }
    }

    if (row0 < N) C[row0 * N + col] = acc0;
    if (row1 < N) C[row1 * N + col] = acc1;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    dim3 block(TILE / 2, TILE);  // 16x32 = 512 threads
    dim3 grid((N + TILE - 1) / TILE, (N + TILE - 1) / TILE);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
