#include "gemm.cuh"

#include <cuda_runtime.h>

#define TILE 32
#define TILE_SM 4
#define PAD 1

__shared__ float As0[TILE][TILE + PAD];
__shared__ float Bs0[TILE + PAD][TILE];
__shared__ float As1[TILE][TILE + PAD];
__shared__ float Bs1[TILE + PAD][TILE];

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int numTiles = (N + TILE - 1) / TILE;

    const int row0 = blockIdx.y * TILE + ty;
    const int row1 = row0 + TILE_SM;
    const int row2 = row0 + TILE_SM * 2;
    const int row3 = row0 + TILE_SM * 3;
    const int col = blockIdx.x * TILE + tx;

    float a0=0,a1=0,a2=0,a3=0;

    for (int t = 0; t < numTiles; ++t) {
        int next = 1 - (t % 2);
        int cur = t % 2;

        if (t > 0) {
            As1[ty][tx] = (row0 < N && t*TILE+tx < N) ? A[row0*N+t*TILE+tx] : 0.0f;
            Bs1[ty][tx] = (t*TILE+ty < N && col < N) ? B[(t*TILE+ty)*N+col] : 0.0f;
            __syncthreads();
            As1[ty+TILE_SM][tx] = (row1 < N && t*TILE+tx < N) ? A[row1*N+t*TILE+tx] : 0.0f;
            Bs1[ty+TILE_SM][tx] = (t*TILE+TILE_SM+ty < N && col < N) ? B[(t*TILE+TILE_SM+ty)*N+col] : 0.0f;
            __syncthreads();
            As1[ty+TILE_SM*2][tx] = (row2 < N && t*TILE+tx < N) ? A[row2*N+t*TILE+tx] : 0.0f;
            Bs1[ty+TILE_SM*2][tx] = (t*TILE+TILE_SM*2+ty < N && col < N) ? B[(t*TILE+TILE_SM*2+ty)*N+col] : 0.0f;
            __syncthreads();
            As1[ty+TILE_SM*3][tx] = (row3 < N && t*TILE+tx < N) ? A[row3*N+t*TILE+tx] : 0.0f;
            Bs1[ty+TILE_SM*3][tx] = (t*TILE+TILE_SM*3+ty < N && col < N) ? B[(t*TILE+TILE_SM*3+ty)*N+col] : 0.0f;
            __syncthreads();
        } else {
            As0[ty][tx] = (row0 < N && t*TILE+tx < N) ? A[row0*N+t*TILE+tx] : 0.0f;
            Bs0[ty][tx] = (t*TILE+ty < N && col < N) ? B[(t*TILE+ty)*N+col] : 0.0f;
            __syncthreads();
            As0[ty+TILE_SM][tx] = (row1 < N && t*TILE+tx < N) ? A[row1*N+t*TILE+tx] : 0.0f;
            Bs0[ty+TILE_SM][tx] = (t*TILE+TILE_SM+ty < N && col < N) ? B[(t*TILE+TILE_SM+ty)*N+col] : 0.0f;
            __syncthreads();
            As0[ty+TILE_SM*2][tx] = (row2 < N && t*TILE+tx < N) ? A[row2*N+t*TILE+tx] : 0.0f;
            Bs0[ty+TILE_SM*2][tx] = (t*TILE+TILE_SM*2+ty < N && col < N) ? B[(t*TILE+TILE_SM*2+ty)*N+col] : 0.0f;
            __syncthreads();
            As0[ty+TILE_SM*3][tx] = (row3 < N && t*TILE+tx < N) ? A[row3*N+t*TILE+tx] : 0.0f;
            Bs0[ty+TILE_SM*3][tx] = (t*TILE+TILE_SM*3+ty < N && col < N) ? B[(t*TILE+TILE_SM*3+ty)*N+col] : 0.0f;
            __syncthreads();
        }

#pragma unroll
        for (int k = 0; k < TILE; ++k) {
            if (cur == 0) {
                a0 += As0[ty][k] * Bs0[k][tx];
                a1 += As0[ty+TILE_SM][k] * Bs0[k][tx];
                a2 += As0[ty+TILE_SM*2][k] * Bs0[k][tx];
                a3 += As0[ty+TILE_SM*3][k] * Bs0[k][tx];
            } else {
                a0 += As1[ty][k] * Bs1[k][tx];
                a1 += As1[ty+TILE_SM][k] * Bs1[k][tx];
                a2 += As1[ty+TILE_SM*2][k] * Bs1[k][tx];
                a3 += As1[ty+TILE_SM*3][k] * Bs1[k][tx];
            }
        }
        __syncthreads();
    }

    if (row0 < N && col < N) C[row0*N+col] = a0;
    if (row1 < N && col < N) C[row1*N+col] = a1;
    if (row2 < N && col < N) C[row2*N+col] = a2;
    if (row3 < N && col < N) C[row3*N+col] = a3;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    dim3 block(TILE, TILE/4);  // 32x4 = 128 threads
    dim3 grid((N + TILE - 1) / TILE, (N + TILE - 1) / TILE);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
