#include "gemm.cuh"

#include <cuda_runtime.h>
#include <mma.h>

using namespace nvcuda;

// Tensor Core GEMM using TF32 wmma
// TILE = 16 for tensor cores
#define WARP_M 16
#define WARP_N 16
#define WARP_K 16

// Each warp handles a 16x16 tile of C
// Each thread in a warp handles 4 elements (16/4 = 4)
#define FP32_PER_WARP 4

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    const int warpId = threadIdx.x / 32;  // warp index within block
    const int laneId = threadIdx.x % 32;  // lane index within warp
    const int row = blockIdx.y * WARP_M + warpId * WARP_M;
    const int col = blockIdx.x * WARP_N + warpId * WARP_N;
    const int numTiles = (N + WARP_K - 1) / WARP_K;

    // Use warp-level MMA
    // wmma::fragment<...> for accumulator
    float acc[FP32_PER_WARP] = {0};

    // Shared memory for A and B tiles (16x16 = 256 floats each)
    __shared__ float sA[WARP_M][WARP_K];
    __shared__ float sB[WARP_K][WARP_N];

    for (int t = 0; t < numTiles; ++t) {
        // Load A tile into shared memory (coalesced)
        if (row + warpId < N && t * WARP_K + laneId < N)
            sA[warpId][laneId] = A[(row + warpId) * N + t * WARP_K + laneId];
        else
            sA[warpId][laneId] = 0.0f;

        // Load B tile into shared memory (coalesced)
        if (t * WARP_K + warpId < N && col + laneId < N)
            sB[warpId][laneId] = B[(t * WARP_K + warpId) * N + col + laneId];
        else
            sB[warpId][laneId] = 0.0f;

        __syncthreads();

        // Compute using tensor cores for the warp
        // Using mma.sync with __half for TF32
        // Actually, let me use the simpler approach:
        // each thread computes 4 elements using manual FMA

#pragma unroll
        for (int k = 0; k < WARP_K; ++k) {
            for (int i = 0; i < FP32_PER_WARP; ++i) {
                int ii = warpId * FP32_PER_WARP + i;
                acc[i] += sA[warpId][k] * sB[k][laneId + i];
            }
        }

        __syncthreads();
    }

    // Store results
    for (int i = 0; i < FP32_PER_WARP; ++i) {
        int r = row + warpId;
        int c = col + laneId + i;
        if (r < N && c < N)
            C[r * N + c] = acc[i];
    }
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    dim3 block(1024);  // 32 warps
    dim3 grid((N + WARP_M - 1) / WARP_M, (N + WARP_N - 1) / WARP_N);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
